fn solve(n: i8, m: i8, horizontal: Vec<char>, vertical: Vec<char>) -> Vec<char> {
    if check_disconnected(n, m, &horizontal, &vertical) {
        return vec!['N', 'O', '\n'];
    } else {
        return vec!['Y', 'E', 'S', '\n'];
    }
}

fn check_disconnected(n: i8, m: i8, horizontal: &Vec<char>, vertical: &Vec<char>) -> bool {
    let first_horizontal = horizontal[0];
    let last_horizontal = horizontal[(n - 1) as usize];
    let first_vertical = vertical[0];
    let last_vertical = vertical[(m - 1) as usize];

    (first_horizontal == '>' && first_vertical == 'v') ||
    (first_horizontal == '<' && last_vertical == 'v') ||
    (last_horizontal == '>' && first_vertical == '^') ||
    (last_horizontal == '<' && last_vertical == '^')
}

fn main() {
    // Example usage
    let n = 3;
    let m = 3;
    let horizontal = vec!['>', '<', '>'];
    let vertical = vec!['^', 'v', 'v'];

    let result = solve(n, m, horizontal, vertical);
    println!("{:?}", result); // Output: ['N', 'O', '\n']
}